initial_condition:
with {
    the SUT in the "initial state"
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Retrieve Attribute with Response Status Code set to 404     and
        Retrieve Attribute with Response Body containing the type 'https://uri.etsi.org/ngsi-ld/errors/ResourceNotFound'     and
        Retrieve Attribute with Response body containing 'title' element
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/attributes/{attribute_name}'
        method set to 'GET'
        Retrieve Attribute with attributeName set to 'airQualityLevel'
}
